    decoderDefinitionSuffix: "DEFINITION",
    anArbitrationSummary: "Mandatory Binding Arbitration & Class Action Waiver: Strips your constitutional right to take your dispute to a public court or jury.",
    anArbitrationPoint1: "You cannot file in civil court without first defeating this clause or filing a Small Claims exemption.",
    anArbitrationPoint2: "Arbitration filing fees often cost $1,500–$5,000+ upfront (though consumer exemption rules under AAA/JAMS may cap consumer share at $250).",
    anArbitrationPoint3: "Arbitration proceedings are private and have extremely limited appeal rights compared to court judgments.",
    anArbitrationAct1: "Check if the contract provides an opt-out window (usually 30 days from signing).",
    anArbitrationAct2: "Check if the clause explicitly exempts Small Claims Court disputes (most standardized adhesion contracts do).",
    anArbitrationAct3: "Assert unconscionability if arbitration fees exceed total dispute value or terms are buried in tiny non-negotiable print.",
    anIndemnitySummary: "Unilateral Indemnification & Hold Harmless: Forces you to pay the other party's legal bills, liabilities, or losses.",
    anIndemnityPoint1: "Extremely dangerous if unreciprocal and placed in standard consumer or tenant contracts.",
    anIndemnityPoint2: "Could make you financially liable for damages caused entirely by the other party.",
    anIndemnityAct1: "Review whether the indemnity extends to their own gross negligence or willful misconduct (which is void as a matter of public policy in almost all jurisdictions).",
    anIndemnityAct2: "Argue that unilateral indemnity clauses in consumer adhesion contracts violate statutory consumer protection acts.",
    anLiquidatedSummary: "Liquidated Damages Clause: Pre-determines the exact dollar penalty you pay if a breach occurs.",
    anLiquidatedPoint1: "Courts will strike down liquidated damages if they constitute an illegal punitive penalty rather than a reasonable pre-estimate of actual anticipated loss.",
    anLiquidatedPoint2: "If the actual damages are readily ascertainable, fixed contractual penalties are frequently unenforceable.",
    anLiquidatedAct1: "Compare the claimed penalty amount against the other party's actual direct out-of-pocket costs.",
    anLiquidatedAct2: "Demand itemized accounting and receipts proving their actual damages.",
    anAsIsSummary: "'As-Is' & Warranty Disclaimers: Attempts to sell goods or property without legal recourse for defects.",
    anAsIsPoint1: "Does NOT protect the seller from affirmative intentional fraud, active concealment of material defects, or statutory disclosure duties.",
    anAsIsPoint2: "Many states prohibit as-is clauses in consumer transactions or require conspicuous magical statutory phrasing.",
    anAsIsAct1: "Document all written text messages, emails, or listings where the seller made affirmative oral promises.",
    anAsIsAct2: "Obtain a certified mechanic or home inspector report showing pre-existing latent defects.",
    anReleaseSummary: "Exculpatory Liability Waiver: Attempting to extinguish all legal liability for personal injuries or property damage.",
    anReleasePoint1: "Clauses attempting to exempt a party from liability for gross negligence, willful injury, or statutory violations are strictly VOID.",
    anReleaseAct1: "Establish that the opposing party exhibited gross negligence (a conscious, voluntary act or omission in reckless disregard of consequences).",
    anAccessSummary: "Landlord Right of Entry / Notice Waiver: Landlord attempting to enter leased premises without statutory advance notice.",
    anAccessPoint1: "Statutory entry rules are non-waivable. Landlords MUST give reasonable written notice (typically 24 hours) during normal business hours.",
    anAccessAct1: "Cite statutory quiet enjoyment rights and non-waivability provisions.",
    anStandardSummary: "Standard Contractual Covenant: Outlines baseline operational duties or general procedural provisions.",
    anStandardPoint1: "Ensure both parties have reciprocal obligations under the plain wording.",
    anStandardAct1: "Maintain time-stamped records of compliance.",

