    anArbitrationSummary: "Arbitrage Contraignant Obligatoire & Renonciation à Recours Collectif : Vous prive du droit constitutionnel de saisir un tribunal public.",
    anArbitrationPoint1: "Vous ne pouvez pas assigner en justice sans contester cette clause ou invoquer une exception pour litiges de proximité.",
    anArbitrationPoint2: "Les frais d'arbitrage initiaux s'élèvent souvent à 1 500 – 5 000 $+ (bien que les règles de protection des consommateurs puissent plafonner la part à 250 $).",
    anArbitrationPoint3: "Les procédures arbitrales sont confidentielles et les voies de recours sont très restreintes comparées aux jugements judiciaires.",
    anArbitrationAct1: "Vérifiez si le contrat prévoit un délai de rétractation (généralement 30 jours après la signature).",
    anArbitrationAct2: "Vérifiez si la clause exclut explicitement les tribunaux de proximité et petits litiges (cas fréquent dans les contrats d'adhésion).",
    anArbitrationAct3: "Invoquez le caractère abusif si les frais d'arbitrage dépassent le montant du litige ou si la clause était dissimulée.",
    anIndemnitySummary: "Indemnisation Unilatérale & Garantie de Non-Recours : Vous oblige à payer les frais de justice et pertes de l'autre partie.",
    anIndemnityPoint1: "Extrêmement dangereuse si elle n'est pas réciproque et insérée dans des contrats types de consommation ou de bail.",
    anIndemnityPoint2: "Pourrait vous rendre financièrement responsable de préjudices causés exclusivement par l'autre partie.",
    anIndemnityAct1: "Vérifiez si l'indemnisation couvre leur propre faute lourde ou dol (nul d'ordre public dans la quasi-totalité des juridictions).",
    anIndemnityAct2: "Soutenez que les clauses d'indemnisation unilatérales dans les contrats d'adhésion violent les lois sur la protection des consommateurs.",
    anLiquidatedSummary: "Clause Pénale / Dommages Forfaitaires : Fixe à l'avance le montant exact des pénalités financières dues en cas d'inexécution.",
    anLiquidatedPoint1: "Les tribunaux annulent ou réduisent la clause pénale si elle présente un caractère manifestement excessif et punitif.",
    anLiquidatedPoint2: "Si le préjudice réel est facilement quantifiable, les pénalités forfaitaires fixes sont fréquemment déclarées inapplicables.",
    anLiquidatedAct1: "Comparez le montant réclamé avec les débours et coûts réels effectivement subis par l'autre partie.",
    anLiquidatedAct2: "Exigez des factures détaillées et des pièces justificatives prouvant la réalité de leur préjudice.",
    anAsIsSummary: "Clause 'En l'État' & Exclusion de Garantie : Tentative de vente sans recours légal pour vices cachés.",
    anAsIsPoint1: "Ne protège PAS le vendeur en cas de dol, dissimulation délibérée de défauts majeurs ou manquement aux obligations légales d'information.",
    anAsIsPoint2: "La législation interdit les clauses exclusives de garantie des vices cachés au détriment des consommateurs.",
    anAsIsAct1: "Conservez tous les SMS, courriels ou annonces dans lesquels le vendeur a fait des déclarations positives.",
    anAsIsAct2: "Obtenez un rapport d'expertise certifié prouvant l'existence antérieure de vices cachés.",
    anReleaseSummary: "Clause Exonératoire de Responsabilité : Tentative d'éteindre toute responsabilité pour dommages corporels ou matériels.",
    anReleasePoint1: "Les clauses exonérant l'auteur d'une faute lourde, d'une atteinte corporelle ou d'un dol sont formellement NULLES.",
    anReleaseAct1: "Établissez que la partie adverse a commis une faute lourde (acte ou omission consciente au mépris du danger).",
    anAccessSummary: "Droit d'Entrée du Bailleur sans Préavis : Tentative du propriétaire d'entrer dans les lieux loués sans respecter le délai légal.",
