    anArbitrationSummary: "強制仲裁条項および集団訴訟放棄：公開裁判所での裁判を受ける憲法上の権利を剥奪する危険条項です。",
    anArbitrationPoint1: "本条項の無効を主張するか少額訴訟の例外を適用しない限り、民事本案訴訟を提起できません。",
    anArbitrationPoint2: "仲裁申立費用は前払いで1,500〜5,000ドル以上かかる場合があります（消費者保護規定により消費者の自己負担は250ドルに制限される場合もあります）。",
    anArbitrationPoint3: "仲裁手続は非公開であり、通常の裁判判決と比較して不服申立て・上訴の機会が著しく制限されます。",
    anArbitrationAct1: "契約に除外申請（オプトアウト）期間が定められているか確認してください（通常は署名後30日以内）。",
    anArbitrationAct2: "少額訴訟裁判所での紛争が適用除外として明記されているか確認してください（多くの標準約款で除外されています）。",
    anArbitrationAct3: "仲裁費用が請求総額を上回る場合や、交渉不可能な極小フォントで隠蔽されていた場合は、公序良俗違反・不当条項を主張してください。",
    anIndemnitySummary: "一方的補償および免責特約：相手方の訴訟費用や損害賠償責任をこちら側に全額負担させる有害条項です。",
    anIndemnityPoint1: "相互義務がなく、一般的な消費者契約や賃貸借約款に記載されている場合は極めて危険です。",
    anIndemnityPoint2: "相手方自身の過失によって引き起こされた損害であっても、こちらが金銭的責任を負わされる恐れがあります。",
    anIndemnityAct1: "相手方自身の重過失や故意による不法行為まで免責対象に含まれているか確認してください（公序良俗に基づきほぼ無効です）。",
    anIndemnityAct2: "付合契約における一方的な免責条項は消費者契約法等の保護規定に明白に違反していると主張してください。",
    anLiquidatedSummary: "損害賠償額の予定条項：債務不履行が発生した場合に支払うべき違約金の金額を事前に固定する条項です。",
    anLiquidatedPoint1: "損害額の合理的な事前見積もりではなく過大な懲罰的制裁とみなされる場合、裁判所により違約金条項が無効化または減額されます。",
    anLiquidatedPoint2: "実際の損害額が容易に算定可能である場合、定額の違約金約定は法的効力を否定されるケースが多くあります。",
    anLiquidatedAct1: "請求されている違約金額と、相手方が実際に被った直接的な実費・損害額を対比してください。",
    anLiquidatedAct2: "相手方に対し、実際の損害を客観的に証明する明細書および領収書の提出を要求してください。",
    anAsIsSummary: "現状有姿売買および瑕疵担保責任免除条項：隠れた欠陥に対する法的追及を遮断しようとする免責特約です。",
    anAsIsPoint1: "売主による積極的な詐欺行為、重大な欠陥の悪意ある隠蔽、または法令上の告知義務違反までは免責されません。",
    anAsIsPoint2: "消費者契約において瑕疵担保責任を全面的に排除する特約は多くの法域で無効とされています。",
    anAsIsAct1: "売主が口頭または文書で性能や品質を明言したメッセージ、電子メール、広告記録をすべて保存してください。",
    anAsIsAct2: "認定技術者または専門検査員による鑑定書を取得し、契約前から存在していた隠れた欠陥を立証してください。",
    anReleaseSummary: "免責・権利放棄約定：人身傷害や財産損害に対する一切の損害賠償請求権を事前放棄させようとする条項です。",
    anReleasePoint1: "重過失、故意による傷害、または法令違反に対する責任を免除する旨の条項は絶対的に無効です。",
    anReleaseAct1: "相手方が重過失（結果の発生を予見できたにもかかわらず著しく配慮を怠った行為または不作為）を犯した事実を立証してください。",
    anAccessSummary: "賃貸人の無断立入り条項：事前告知なしに賃貸借物件内へ無断侵入することを認める有害条項です。",
    anAccessPoint1: "住居の不可侵と平穏保有権は放棄不能です。賃貸人は平日の営業時間内に書面による事前予告（通常24時間以上前）を行う法的義務があります。",
    anAccessAct1: "平穏享受権および事前通知義務の放棄無効を定めた法令条文を明確に引用して抗弁してください。",
    anStandardSummary: "標準的契約条項：基本的な履行義務または一般的手続規定を定めた条項です。",
    anStandardPoint1: "条項の文面において双方に公平な対価・相互義務が課されているか確認してください。",
    anStandardAct1: "合意事項を履行したことを証明するタイムスタンプ付きの客観的記録を保存してください。",

